// Process companies that need enrichment
const response = $input.item.json;

if (!response.result || !Array.isArray(response.result)) {
  throw new Error('Invalid Odoo response');
}

const companies = response.result;
const today = new Date();
const sixtyDaysAgo = new Date(today.getTime() - 60 * 24 * 60 * 60 * 1000);

// Filter companies needing enrichment
const companiesToEnrich = companies.filter(company => {
  // Skip if enriched in last 60 days
  if (company.x_last_enriched) {
    const lastEnriched = new Date(company.x_last_enriched);
    if (lastEnriched > sixtyDaysAgo) {
      return false;
    }
  }
  return true;
}).map(company => ({
  odoo_id: company.id,
  company_name: company.name,
  website: company.website || '',
  email: company.email || '',
  linkedin_company_url: company.x_linkedin_company_url || '',
  last_enriched: company.x_last_enriched
}));

// Limit batch size (API quota)
const BATCH_LIMIT = 20;
const batch = companiesToEnrich.slice(0, BATCH_LIMIT);

if (batch.length === 0) {
  return {
    json: {
      message: 'No companies need enrichment',
      total_companies: companies.length,
      batch_size: 0
    }
  };
}

return batch.map(company => ({ json: company }));

// Process executive search results
const company = $('Rate Limit (10s)').item.json;
const searchResponse = $input.item.json;

const result = {
  odoo_company_id: company.odoo_id,
  company_name: company.company_name,
  executives_found: [],
  total_found: 0,
  api_status: 'success',
  enriched_at: new Date().toISOString(),
  notes: ''
};

// Check for API errors
if (searchResponse.statusCode && searchResponse.statusCode !== 200) {
  result.api_status = 'error';
  result.notes = `API Error: ${searchResponse.statusCode}`;
  return { json: result };
}

const employees = searchResponse.body?.employees || searchResponse.employees || [];

if (employees.length === 0) {
  result.notes = 'No executives found matching criteria';
  return { json: result };
}

// Priority roles (in order of importance)
const priorityRoles = [
  'ceo', 'chief executive',
  'cto', 'chief technology',
  'cio', 'chief information',
  'cdo', 'chief digital', 'chief data',
  'cso', 'chief sales', 'chief strategy',
  'cfo', 'chief financial',
  'coo', 'chief operating',
  'cmo', 'chief marketing',
  'founder', 'co-founder',
  'owner',
  'president',
  'vp', 'vice president',
  'director',
  'head of',
  'board member', 'board of directors'
];

// Extract and rank executives
const processedExecs = [];

for (const emp of employees) {
  const profile = emp.profile;
  if (!profile) continue;

  const title = (profile.headline || profile.occupation || '').toLowerCase();
  const fullName = profile.full_name || `${profile.first_name || ''} ${profile.last_name || ''}`.trim();

  if (!fullName) continue;

  // Calculate priority score
  let priorityScore = 100;
  for (let i = 0; i < priorityRoles.length; i++) {
    if (title.includes(priorityRoles[i])) {
      priorityScore = i;
      break;
    }
  }

  // Extract email if available
  let email = '';
  if (profile.personal_emails && profile.personal_emails.length > 0) {
    email = profile.personal_emails[0];
  } else if (emp.email) {
    email = emp.email;
  }

  processedExecs.push({
    name: fullName,
    title: profile.headline || profile.occupation || 'Executive',
    linkedin_url: profile.public_identifier 
      ? `https://linkedin.com/in/${profile.public_identifier}`
      : profile.linkedin_profile_url || '',
    email: email,
    location: profile.city || profile.country || '',
    seniority: priorityScore < 10 ? 'C-Suite' : (priorityScore < 20 ? 'VP/Director' : 'Manager'),
    priority_score: priorityScore,
    summary: (profile.summary || '').substring(0, 200)
  });
}

// Sort by priority and take top executives
processedExecs.sort((a, b) => a.priority_score - b.priority_score);
const topExecutives = processedExecs.slice(0, 5); // Max 5 per company

result.executives_found = topExecutives;
result.total_found = topExecutives.length;
result.notes = `Found ${topExecutives.length} executives (${processedExecs.length} total matches)`;

return { json: result };

// Track created contacts per company
const createdContacts = $input.all();
const companyData = $('Process & Rank Executives').item.json;

const result = {
  odoo_company_id: companyData.odoo_company_id,
  company_name: companyData.company_name,
  contacts_created: createdContacts.length,
  contact_ids: [],
  enriched_at: companyData.enriched_at
};

for (const contact of createdContacts) {
  if (contact.json.result) {
    result.contact_ids.push(contact.json.result);
  }
}

return { json: result };

