// Generate final enrichment report
const allResults = $input.all();

const summary = {
  run_date: new Date().toISOString(),
  companies_processed: allResults.length,
  total_contacts_created: 0,
  companies_with_executives: 0,
  companies_without_executives: 0,
  contacts_by_company: [],
  api_errors: 0
};

for (const item of allResults) {
  const data = item.json;

  if (data.contacts_created && data.contacts_created > 0) {
    summary.companies_with_executives++;
    summary.total_contacts_created += data.contacts_created;
    summary.contacts_by_company.push({
      company: data.company_name,
      contacts_added: data.contacts_created
    });
  } else {
    summary.companies_without_executives++;
  }
}

summary.report = `
# Company Enrichment Report
Date: ${new Date().toLocaleDateString()}

## Summary
- Companies Processed: ${summary.companies_processed}
- ✅ Successfully Enriched: ${summary.companies_with_executives}
- ⚠️ No Executives Found: ${summary.companies_without_executives}
- 👥 Total Contacts Created: ${summary.total_contacts_created}

## Contacts Added by Company
${summary.contacts_by_company.map(c => `- ${c.company}: ${c.contacts_added} executives`).join('\n')}

## Next Steps
- Review ${summary.companies_without_executives} companies that need manual research
- Verify newly added executive contact information
- Check for duplicate contacts
`;

return { json: summary };
